export const feedbackKey='clue:feedback:v1';
export const feedbackStatuses=['pending','reviewing','replied'];
export function readFeedback(raw){
 try{const rows=JSON.parse(raw||'[]');if(!Array.isArray(rows))return [];const seen=new Set();return rows.filter(r=>{if(!r||typeof r.id!=='string'||seen.has(r.id)||typeof r.text!=='string'||!r.text.trim()||r.text.length>800||!feedbackStatuses.includes(r.status)||!Number.isFinite(Date.parse(r.at)))return false;seen.add(r.id);return true;}).map(r=>({id:r.id,text:r.text,place:typeof r.place==='string'?r.place:null,at:r.at,status:r.status,simulated:r.simulated===true,reviewedAt:typeof r.reviewedAt==='string'?r.reviewedAt:null,repliedAt:typeof r.repliedAt==='string'?r.repliedAt:null}));}catch{return [];}
}
export function createFeedback(text,place=null,now=new Date().toISOString(),id=globalThis.crypto.randomUUID()){
 const value=String(text||'').trim();if(!value||value.length>800)return null;
 return {id,text:value,place,at:now,status:'pending',simulated:false,reviewedAt:null,repliedAt:null};
}
export function advanceFeedback(record,now=new Date().toISOString()){
 if(record.status==='pending')return {...record,status:'reviewing',simulated:true,reviewedAt:now};
 if(record.status==='reviewing')return {...record,status:'replied',simulated:true,repliedAt:now};
 return {...record};
}
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupFeedback({en,getContext,placeName,toast}){
 const dialog=document.querySelector('#feedbackDialog'),t=(zh,eng)=>en?eng:zh,$=s=>dialog.querySelector(s);
 let records=[],active=null,context=null,sample=null;try{records=readFeedback(localStorage.getItem(feedbackKey));}catch{}
 const status=r=>({pending:t('待处理','Pending'),reviewing:t('处理中','In review'),replied:t('已回复','Replied')})[r.status];
 const stamp=value=>{const date=new Date(value);return Number.isFinite(+date)?date.toLocaleString(en?'en-GB':'zh-CN',{dateStyle:'medium',timeStyle:'short'}):'—';};
 const persist=()=>{try{localStorage.setItem(feedbackKey,JSON.stringify(records));return true;}catch{toast(t('无法保存到浏览器；反馈仅在当前页面保留。','Browser storage unavailable; feedback lasts for this page only.'));return false;}};
 dialog.classList.add('feedback-center');
 dialog.innerHTML=`<button class="dialog-close" id="closeFeedback" aria-label="${t('关闭','Close')}">×</button><p class="eyebrow">THE CORRESPONDENCE FILE</p><h2 id="feedbackTitle">${t('每条反馈，<em>都有下文。</em>','Every clue.<br><em>A follow-up.</em>')}</h2><p class="feedback-scope">${t('原型演示 · 反馈保存在此浏览器。没有发送给学校；处理状态与回信可通过演示预览。','Prototype demo · feedback stays in this browser. Nothing is sent to the university; handling and replies can be previewed as a simulation.')}</p><div class="feedback-tabs" role="group" aria-label="${t('反馈功能','Feedback views')}"><button id="composeFeedback" aria-pressed="true">${t('写反馈','Write a note')}</button><button id="myFeedback" aria-pressed="false">${t('我的反馈与回信','My notes & replies')} <span id="feedbackCount"></span></button></div><form id="feedbackCompose"><p id="feedbackContext" class="small"></p><label class="field">${t('观察或建议','Observation or suggestion')}<textarea id="feedbackText" rows="4" maxlength="800" required placeholder="${t('例如：楼层提示不够清楚，或入口线索有误…','For example: the floor clue was unclear, or the entrance detail needs checking…')}"></textarea></label><button id="saveFeedback" class="primary full" type="submit">${t('保存反馈并查看进度','Save note & view progress')}</button></form><section id="feedbackHistory" hidden><div class="feedback-history-head"><span class="eyebrow">${t('本浏览器的反馈档案','NOTES IN THIS BROWSER')}</span><button id="feedbackExample" class="text-button">${t('预览回信示例','Preview a sample reply')}</button></div><div id="feedbackRecords"></div></section><section id="feedbackDetail" hidden></section>`;
 $('#closeFeedback').onclick=()=>dialog.close();
 function view(which){$('#feedbackCompose').hidden=which!=='compose';$('#feedbackHistory').hidden=which!=='history';$('#feedbackDetail').hidden=which!=='detail';$('#composeFeedback').setAttribute('aria-pressed',String(which==='compose'));$('#myFeedback').setAttribute('aria-pressed',String(which!=='compose'));$('#feedbackCount').textContent=records.length?String(records.length):'';}
 function history(){sample=null;active=null;view('history');$('#feedbackRecords').innerHTML=records.length?records.map(r=>`<button class="feedback-record" data-feedback-id="${escape(r.id)}"><span class="feedback-record-top"><small>${escape(stamp(r.at))}</small><span class="feedback-status ${r.status}">${status(r)}${r.simulated?' · '+t('演示','demo'):''}</span></span><strong>${escape(r.text)}</strong><span class="feedback-record-bottom">${escape(r.place?placeName(r.place):t('整体体验','General experience'))}<span>${r.status==='replied'?t('查看回信','Read reply'):t('查看进度','View progress')} ↗</span></span></button>`).join(''):`<div class="feedback-empty"><span aria-hidden="true">✉</span><h3>${t('还没有反馈档案','No notes filed yet')}</h3><p>${t('保存一条反馈后，可以在这里查看进度与回信。也可先预览回信示例。','Save a note to keep its progress and replies here, or preview the sample reply first.')}</p></div>`;$('#feedbackRecords').querySelectorAll('[data-feedback-id]').forEach(b=>b.onclick=()=>detail(b.dataset.feedbackId));}
 function detail(id){active=id;const r=sample?.id===id?sample:records.find(r=>r.id===id);if(!r){history();return;}view('detail');const phase=feedbackStatuses.indexOf(r.status);$('#feedbackDetail').innerHTML=`<button id="feedbackBack" class="text-button">← ${t('全部反馈','All notes')}</button><div class="feedback-detail-heading"><small>FILE / ${escape(r.id.slice(0,8).toUpperCase())}</small><span class="feedback-status ${r.status}">${status(r)}${r.simulated?' · '+t('演示','demo'):''}</span></div>${sample?`<p class="feedback-simulation-label">${t('独立演示案例 · 不属于已提交的反馈','SAMPLE CASE · NOT A SUBMITTED NOTE')}</p>`:''}<p class="feedback-original">${escape(r.text)}</p><p class="small">${escape(r.place?placeName(r.place):t('整体体验','General experience'))} · ${escape(stamp(r.at))}</p><ol class="feedback-progress" aria-label="${t('反馈处理进度','Feedback progress')}">${feedbackStatuses.map((s,i)=>`<li class="${i<=phase?'complete':''}" ${i===phase?'aria-current="step"':''}><b>${i<phase?'✓':i+1}</b><span>${({pending:t('待处理','Pending'),reviewing:t('处理中','In review'),replied:t('已回复','Replied')})[s]}</span></li>`).join('')}</ol><p class="feedback-status-note">${r.status==='pending'?t('已在本地保存，尚未处理；没有连接真实接收方。','Saved locally and awaiting review. No real recipient is connected.'):r.status==='reviewing'?t('演示状态：正在核对线索。尚未收到回信。','Simulated status: the clue is being reviewed. No reply yet.'):t('演示状态：已有回信。回信不代表地点信息已经核实或问题已经修复。','Simulated status: a reply is available. This does not mean the place is verified or the issue is fixed.')}</p>${r.status==='replied'?`<article class="feedback-reply"><span class="eyebrow">${t('设计团队 · 演示回信','DESIGN TEAM · SIMULATED REPLY')}</span><p>${t('感谢指出这条线索中的问题。下一轮将核对相关地点信息与提示表达，并测试修改是否更清楚。若现场标识与页面不同，请先参考现场标识或咨询工作人员。','Thank you for flagging this clue. The next iteration would check the place information and wording, then test whether the revised guidance is clearer. If on-site signs differ from the page, follow those signs or ask a member of staff.')}</p><small>${escape(stamp(r.repliedAt))} · ${t('示例内容，未由工作人员发送','Example content; not sent by staff')}</small></article>`:`<div class="feedback-no-reply">✉ ${t('暂无回信','No reply yet')}</div>`}${!sample&&r.status!=='replied'?`<details class="feedback-demo-controls"><summary>${t('演示工具：预览处理与回信','Demo tools: preview handling & reply')}</summary><p>${t('仅模拟后台处理，不会通知真实工作人员。','Simulates backend handling only. No real staff are notified.')}</p><button id="advanceFeedback" class="outline">${r.status==='pending'?t('模拟开始处理','Simulate review started'):t('模拟收到回信','Simulate a reply')}</button></details>`:''}`;$('#feedbackBack').onclick=history;$('#advanceFeedback')?.addEventListener('click',()=>{records=records.map(item=>item.id===id?advanceFeedback(item):item);persist();detail(id);});$('#feedbackDetail').focus({preventScroll:true});}
 $('#feedbackDetail').tabIndex=-1;
 $('#composeFeedback').onclick=()=>view('compose');$('#myFeedback').onclick=history;
 $('#feedbackExample').onclick=()=>{const now=new Date().toISOString();sample=advanceFeedback(advanceFeedback(createFeedback(t('在到达楼层之后，不清楚应该看哪个指示牌。','After reaching the floor, it was unclear which sign to look for.'),null,now,'sample-reply'),now),now);detail(sample.id);};
 $('#feedbackCompose').onsubmit=e=>{e.preventDefault();const note=createFeedback($('#feedbackText').value,context);if(!note){$('#feedbackText').focus();return;}records.unshift(note);const stored=persist();$('#feedbackText').value='';detail(note.id);if(stored)toast(t('反馈已保存于本浏览器，可随时查看进度。','Note saved in this browser. Progress is available in My notes & replies.'));};
 return {open(options={}){if(options.compose){$('#feedbackText').value='';context=options.place??getContext();}else if(!$('#feedbackText').value.trim())context=getContext();$('#feedbackContext').textContent=context?t('关联地点：','Linked place: ')+placeName(context):t('整体体验反馈','General experience feedback');if(!options.compose&&records.length&&!$('#feedbackText').value.trim())history();else view('compose');dialog.showModal();},refresh(){if(dialog.open&&active)detail(active);}};
}
